import{_ as d,o as e,c as a,ag as r}from"./chunks/framework.CmaAMB6e.js";const p=JSON.parse('{"title":"Agent 开发学习模块","description":"","frontmatter":{},"headers":[],"relativePath":"agent/index.md","filePath":"agent/index.md","lastUpdated":null}'),o={name:"agent/index.md"};function n(l,t,i,h,c,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="agent-开发学习模块" tabindex="-1">Agent 开发学习模块 <a class="header-anchor" href="#agent-开发学习模块" aria-label="Permalink to &quot;Agent 开发学习模块&quot;">​</a></h1><blockquote><p>本模块是独立的 AI Agent 开发学习线。使用者是前端工程师——熟悉 JS/TS 与 Web 工程,但对大模型应用开发(LLM 调用、工具编排、RAG、多 Agent)缺乏系统认知。</p><p>主线为「LLM 心智模型 → Prompt 与结构化输出 → 工具能力 → 知识与记忆 → Agent 架构 → 工程化与生产化 → 综合实战」。</p><p><strong>技术栈说明</strong>:本线以 <strong>Python 生态为主</strong>(LangChain / LangGraph / OpenAI &amp; Anthropic SDK),因为 Agent 领域最成熟、资料最全的方案都在这一侧。但每篇的「前端对照」小节都会把概念映射回你熟悉的 TS/JS 视角——你不需要先学 Python,只需要能读懂它的语法。</p></blockquote><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>语言</td><td>Python 3.11+(主线)/ TypeScript(对照与前端集成)</td></tr><tr><td>模型接入</td><td>OpenAI SDK / Anthropic SDK</td></tr><tr><td>Agent 框架</td><td>LangGraph(状态机与编排)/ LangChain(组件与集成)</td></tr><tr><td>结构化输出</td><td>Pydantic + instructor</td></tr><tr><td>向量与检索</td><td>Chroma / Qdrant / pgvector,+ BM25 混合检索</td></tr><tr><td>工具协议</td><td>Function Calling / MCP(Model Context Protocol)</td></tr><tr><td>后端与流式</td><td>FastAPI + SSE</td></tr><tr><td>可观测</td><td>LangSmith / Langfuse / OpenTelemetry</td></tr><tr><td>测试</td><td>pytest + LLM-as-Judge</td></tr><tr><td>IDE</td><td>VS Code / Cursor</td></tr></tbody></table><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>学完本模块后,你应该能:</p><ol><li>建立正确的 Agent 心智模型,分清「ChatBot」与「Agent」的工程差异</li><li>写出稳定的 Prompt,并让模型可靠地返回可解析的结构化数据</li><li>为 Agent 设计与编排工具,包括代码执行沙箱、文件操作与网络能力</li><li>构建 RAG 流水线并优化检索质量,设计短期与长期记忆</li><li>实现 ReAct、规划-执行、反思、多 Agent 协作等主流架构模式</li><li>用状态机控制流程,并在关键节点接入人工审批</li><li>把 Agent 做成产品:流式交互、错误降级、权限治理、可观测与成本控制</li><li>搭建评估体系,用数据驱动迭代,而非靠感觉调 Prompt</li></ol><h2 id="概念清单-29-篇" tabindex="-1">概念清单（29 篇） <a class="header-anchor" href="#概念清单-29-篇" aria-label="Permalink to &quot;概念清单（29 篇）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>概念</th></tr></thead><tbody><tr><td>1 基础层</td><td>01 LLM 与 Agent 心智模型 · 02 Prompt 工程 · 03 结构化输出 · 04 API 工程实践 · 05 模型选型与本地部署</td></tr><tr><td>2 工具能力层</td><td>06 Function Calling · 07 工具设计与编排 · 08 代码执行沙箱 · 09 文件与命令操作 · 10 搜索与浏览器</td></tr><tr><td>3 知识记忆层</td><td>11 Embedding 与向量检索 · 12 RAG 流水线 · 13 检索质量优化 · 14 记忆系统 · 15 上下文工程</td></tr><tr><td>4 Agent 架构层</td><td>16 ReAct 循环 · 17 规划与分解 · 18 反思与自纠 · 19 Multi-Agent · 20 状态机与人在回路</td></tr><tr><td>5 工程化层</td><td>21 流式与前端集成 · 22 错误与韧性 · 23 评估与测试 · 24 可观测与成本 · 25 安全与权限 · 26 MCP 生态 · 27 长时运行 · 28 产品化设计</td></tr><tr><td>6 综合实战</td><td>29 综合实战项目</td></tr></tbody></table><h2 id="如何使用本模块" tabindex="-1">如何使用本模块 <a class="header-anchor" href="#如何使用本模块" aria-label="Permalink to &quot;如何使用本模块&quot;">​</a></h2><ol><li>先读 <code>setup.md</code> 把环境搭起来(Python 环境 + API Key + 可观测账号)</li><li>按 <code>learning-path.md</code> 的阶段顺序推进,每篇一个概念,自成闭环</li><li>每篇末尾有练习建议,可用 <code>/practice agent &lt;概念&gt;</code> 生成针对性练习</li><li>学完一个阶段,用 <code>/assess agent &lt;等级&gt;</code> 自测,达标参考 <code>levels.md</code></li><li>在 <code>progress.md</code> 更新状态,在 <code>notes.md</code> 沉淀踩坑</li></ol><h2 id="与其他技能线的关系" tabindex="-1">与其他技能线的关系 <a class="header-anchor" href="#与其他技能线的关系" aria-label="Permalink to &quot;与其他技能线的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技能线</th><th>关联点</th></tr></thead><tbody><tr><td>Node.js</td><td>第 04 篇 API 工程、第 21 篇流式后端的 TS 对照</td></tr><tr><td>前端</td><td>第 21 篇流式渲染、第 28 篇交互设计</td></tr><tr><td>数据库</td><td>第 11/12 篇向量检索与 pgvector</td></tr><tr><td>系统设计</td><td>第 22 篇韧性设计、第 27 篇长时任务的架构视角</td></tr><tr><td>Python</td><td>本线的实现语言,若不熟悉 Python 语法可先看 Python 线的前 5 篇</td></tr></tbody></table><h2 id="一句提醒" tabindex="-1">一句提醒 <a class="header-anchor" href="#一句提醒" aria-label="Permalink to &quot;一句提醒&quot;">​</a></h2><p>Agent 工程最大的认知陷阱,是把它当成「调 API 写 Prompt」。真正决定成败的是<strong>工程部分</strong>:工具怎么设计、上下文怎么裁剪、循环怎么熔断、失败怎么降级、效果怎么度量。本线 29 篇里有 20 篇在讲这些。</p>',15)])])}const A=d(o,[["render",n]]);export{p as __pageData,A as default};
